mapper.update:
UPDATE SJG1JC
   SET ymd              = #{ymd}
     , CY_GB            = #{cyGb}
     , balh_co          = #{balhCo}
     , JM_NM            = #{jmNm}
     , jg_tr_co_cd      = #{trCoCd}
     , jg_tr_co_nm      = #{xxTrCoCd}
     , START_YMD        = #{startYmd}
     , END_YMD          = #{endYmd}
     , SJ_YMD           = #{sjYmd}
     , NABIB_YMD        = #{nabibYmd}
     , TOT_B_JUSU       = #{totBJusu}
     , TOT_G_JUSU       = #{totGJusu}
     , tot_g_danga      = #{totGDanga}
     , TOT_G_AEK        = #{totGAek}
     , cy_jm_cd         = #{cyJmCd}
     , sj_jm_cd         = #{sjJmCd}
     , susu_per         = #{susuPer}
     , jkm_per          = #{jkmPer}
     , competition_rate = #{competitionRate}
     , BIGO             = #{bigo}
     , UPD_USER         = #{updUser}
 WHERE JC_JOIN          = #{jcJoin}

MERGE INTO sjg1jc_tr tr
USING DUAL
   ON (tr.corp_gr = #{corpGr} AND tr.jc_join = #{jcJoin} AND tr.jg_tr_co_cd = #{jgTrCoCd})
WHEN MATCHED THEN
   UPDATE SET tr.cy_ymd    = #{cyYmd}
            , tr.cy_jusu   = #{cyJusu}
            , tr.cy_danga  = #{cyDanga}
            , tr.cy_aek    = #{cyAek}
            , tr.cy_jkm    = #{cyJkm}
            , tr.cy_user   = #{cyUser}
            , tr.lock_end  = #{lockEnd}
            , tr.nabib_ymd = #{nabibYmd}
            , tr.cy_type   = #{cyType}
            , tr.bigo      = #{bigo}
WHEN NOT MATCHED THEN
   INSERT (corp_gr, jc_join, jg_tr_co_cd, cy_ymd, cy_jusu, cy_danga, cy_aek, cy_jkm, cy_user, lock_end, nabib_ymd, cy_type, bigo)
   VALUES (#{corpGr}, #{jcJoin}, #{jgTrCoCd}, #{cyYmd}, #{cyJusu}, #{cyDanga}, #{cyAek}, #{cyJkm}, #{cyUser}, #{lockEnd}, #{nabibYmd}, #{cyType}, #{bigo})

UPDATE sjg1fc
   SET cy_jusu  = #{cyJusu}
     , cy_aek   = #{cyAek}
     , cy_jkm   = #{cyJkm}
     , cy_susu  = #{cySusu}
     , lock_end = #{lockEnd}
 WHERE corp_gr     = #{corpGr}
   AND jc_join     = #{jcJoin}
   AND jg_tr_co_cd = #{jgTrCoCd}
   AND fund_cd     = #{fundCd}
